  if(/vín|vin|wine/.test(q))return`Pre milovníkov vína je ideálny výlet Malé Karpaty: Pezinok, Modra, Červený Kameň, Smolenice a Trnava. Trvá 9–10 hodín, od 99 € z Bratislavy.\n${SITE}/vylety/male-karpaty`;
